# Compute test point convex hull and cell-center mask
points=[(r,c) for r,cs in pts_byrow.items() for c in cs]
def hull(points):
 ps=sorted(set((c,r) for r,c in points))
 def cr(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
 lo=[]
 for p in ps:
  while len(lo)>=2 and cr(lo[-2],lo[-1],p)<=0:lo.pop()
  lo.append(p)
 up=[]
 for p in reversed(ps):
  while len(up)>=2 and cr(up[-2],up[-1],p)<=0:up.pop()
  up.append(p)
 return lo[:-1]+up[:-1]
h=hull(points)
h

